"""The ``dates`` capability: one date arithmetic for a page and for Python.

Import it as ``from workpeg.ui import dates``. In a compiled page every
``dates.<fn>(...)`` call becomes ``Workpeg.dates.<fn>(...)`` in the runtime;
this module is the same functions, written again in Python so that library
code built on them runs under CPython too, and so that a test can hold the
two implementations against each other. ``tests/ui/test_dates_parity.py``
calls both ten thousand times and requires the same answers.

Values are ISO 8601 strings, never ``datetime`` objects::

    "2025-12-16"            a date
    "2025-12"               a month
    "14:30" / "14:30:15"    a time, always 24-hour
    "2025-12-16T14:30"      a datetime: wall-clock time with no offset

They sort and compare with ``<``, survive JSON and ``State`` unchanged, and
are what a ``Field`` already holds.

Every function is total. Input that is not a real value of the right kind
(``"2025-02-30"``, ``"2025-12-16<img>"``, ``None``, a number) gives ``None``
(``False`` from a predicate) and never raises, because the runtime twin runs
inside event handlers and renders, where a throw would break the page.

Arguments are positional only, here and in the compiler, which refuses a
keyword argument to any ``dates`` function.

The arithmetic is integer day numbers (Hinnant's ``days_from_civil``), not
``datetime``, so the module is independent of the oracle
``tests/ui/test_dates_twin.py`` checks it against, day by day from 1600 to
2400. Time zones are read through :mod:`zoneinfo`.

``format`` and ``format_range`` speak en-US only, matching ICU's en-US output
with ordinary spaces; every other locale is formatted by the browser alone.
Formatted text is for display: never compare or parse it.
"""
from __future__ import annotations

import re
import time
from datetime import datetime, timedelta, timezone
from functools import lru_cache
from typing import Any

from zoneinfo import ZoneInfo, available_timezones

MONDAY, TUESDAY, WEDNESDAY, THURSDAY, FRIDAY, SATURDAY, SUNDAY = range(1, 8)

# The strict parser. [0-9], never \d: Python's \d and int() both accept
# "２０２５" and "٢٠٢٥". The empty groups line a time's parts up with a
# datetime's, as in the runtime. Nothing longer than 32 characters reaches a
# regex at all.
_ISO = (
    ("d", re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})", re.ASCII)),
    ("m", re.compile(r"([0-9]{4})-([0-9]{2})", re.ASCII)),
    ("t", re.compile(r"()()()([0-9]{2}):([0-9]{2})(?::([0-9]{2}))?", re.ASCII)),
    ("x", re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})"
                     r"T([0-9]{2}):([0-9]{2})(?::([0-9]{2}))?", re.ASCII)),
)
# A zone starts with a letter, as every IANA name does (Etc/GMT+5 still
# passes): node 22 and today's browsers read "+05:30" as a fixed offset, node
# 20 and zoneinfo as no zone at all, so both sides refuse it.
_ZONE_RE = re.compile(r"[A-Za-z][A-Za-z0-9_+\-/]{0,63}", re.ASCII)
_LOCALE_RE = re.compile(r"[A-Za-z]{2,8}(?:-[A-Za-z0-9]{1,8}){0,7}", re.ASCII)
_REGION_RE = re.compile(r"[A-Z]{2}|[0-9]{3}", re.ASCII)

# The weekday a week starts on, wherever it is not Monday: regions, then the
# likely region of a bare language, then of a language-script pair whose
# script moves it (the one place Monday is listed). A digit sets the day for
# the codes after it. Written by tools/gen_week_data.mjs from node's ICU; the runtime holds
# the same two strings, and tests/ui/test_week_data.py keeps them equal.
# @week-data
# ICU 76.1
_WEEK_REGIONS = "5MV 6AF BH DJ DZ EG IQ IR JO KW LY OM QA SD SY 7AG AS BD BR BS BT BW BZ CA CO DM DO ET GT GU HK HN ID IL IN JM JP KE KH KR LA MH MM MO MT MX MZ NI NP PA PE PH PK PR PT PY SA SG SV TH TT TW UM US VE VI WS YE ZA ZW"  # noqa: E501
_WEEK_LANGS = "1en-Shaw yue-Hans 6ar az-Arab ckb fa kab ku-Arab lrc mzn ps syr uz-Arab 7af am ars as bgc bho bn brx ccp ceb chr csw dav doi dz ebu en fil gu guz haw he hi id ja jv kam kgp ki kln km kn ko kok ks kxv lkt lo luo luy mai mas mer mgh ml mni mr mt my nd ne nso om or pa pt qu raj sa saq sat sd seh sn st su ta te tg-Arab th ti tn ur vmw xh xnr yrl yue zh-Bopo zh-Hanb zh-Hant zu"  # noqa: E501
# @end week-data

_MAX_SAFE = 2 ** 53 - 1
_DAY_MS = 86_400_000
# 400 Gregorian years, the cycle after which the calendar repeats exactly.
_CYCLE_MS = 146097 * _DAY_MS
_EPOCH = datetime(1970, 1, 1, tzinfo=timezone.utc)


def _clock() -> int:
    """Now, in epoch milliseconds. The one place the system clock is read,
    so a test can stand in for it."""
    return time.time_ns() // 1_000_000


# ── day numbers ──────────────────────────────────────────────────────────

def _days(y: int, m: int, d: int) -> int:
    """Hinnant's days_from_civil: day 0 is 1970-01-01. Only years 1–9999
    get here, so after the March shift ``y`` is never negative."""
    y -= m < 3
    return (y * 365 + y // 4 - y // 100 + y // 400
            + (153 * ((m + 9) % 12) + 2) // 5 + d - 719469)


def _civil(n: int) -> tuple[int, int, int]:
    """Hinnant's civil_from_days, the inverse of :func:`_days`."""
    n += 719468
    era = n // 146097
    doe = n - era * 146097
    yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
    doy = doe - 365 * yoe - yoe // 4 + yoe // 100
    mp = (5 * doy + 2) // 153
    m = (mp + 2) % 12 + 1
    return yoe + era * 400 + (m < 3), m, doy - (153 * mp + 2) // 5 + 1


def _leap(y: int) -> bool:
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)


def _dim(y: int, m: int) -> int:
    return 28 + _leap(y) if m == 2 else 30 + ((m + (m > 7)) & 1)


def _wd(n: int) -> int:
    """The ISO weekday of a day number: 1970-01-01 was a Thursday."""
    return (n % 7 + 3) % 7 + 1


_LO = _days(1, 1, 1)
_HI = _days(9999, 12, 31)


# ── parsing ──────────────────────────────────────────────────────────────

def _int(x: Any) -> int | None:
    """``x`` as an integer the runtime would read the same way, else None.

    A whole float counts, because a page cannot tell ``2.0`` from ``2``; a
    bool does not, because a page can. Past 2**53 the runtime loses
    integers, so those are refused on both sides alike.
    """
    if isinstance(x, bool):
        return None
    if isinstance(x, float) and x.is_integer():
        x = int(x)
    if isinstance(x, int) and abs(x) <= _MAX_SAFE:
        return x
    return None


def _ok(p: dict) -> bool:
    y, m, d, h, mi, s = (p.get(k) for k in ("y", "m", "d", "h", "mi", "s"))
    if y is not None and not (
            0 < y < 10000 and 0 < m < 13
            and (d is None or 0 < d <= _dim(y, m))):
        return False
    return h is None or (0 <= h < 24 and 0 <= mi < 60
                         and (s is None or 0 <= s < 60))


def _parse(s: Any) -> dict | None:
    """``{k, y, m, d, h, mi, s}`` for a real ISO value (k is ``d`` date,
    ``m`` month, ``t`` time or ``x`` datetime; absent parts are None)."""
    if not isinstance(s, str) or len(s) > 32:
        return None
    for kind, rx in _ISO:
        g = rx.fullmatch(s)
        if g:
            n = [int(x) if x else None for x in g.groups()]
            n += [None] * (6 - len(n))
            p = {"k": kind, "y": n[0], "m": n[1], "d": n[2],
                 "h": n[3], "mi": n[4], "s": n[5]}
            return p if _ok(p) else None
    return None


def _iso(p: dict, k: str | None = None) -> str:
    k = k or p["k"]
    day = "" if k == "t" else f"{p['y']:04d}-{p['m']:02d}" + (
        "" if k == "m" else f"-{p['d']:02d}")
    clock = ""
    if k in ("t", "x"):
        clock = f"{p['h']:02d}:{p['mi']:02d}" + (
            "" if p.get("s") is None else f":{p['s']:02d}")
    return day + ("T" if day and clock else "") + clock


def _p(v: Any, kinds: str) -> dict | None:
    """``v`` parsed, accepted only as one of ``kinds``."""
    p = _parse(v)
    return p if p and p["k"] in kinds else None


def _n(p: dict) -> int:
    return _days(p["y"], p["m"], p["d"])


def _at(n: int, p: dict, k: str | None = None) -> str | None:
    """Day number ``n``, keeping ``p``'s time, as kind ``k``; None outside
    years 1–9999."""
    if not _LO <= n <= _HI:
        return None
    y, m, d = _civil(n)
    return _iso({"y": y, "m": m, "d": d, "h": p.get("h"), "mi": p.get("mi"),
                 "s": p.get("s")}, k or p["k"])


def _chk(p: dict) -> str | None:
    return _iso(p) if _ok(p) else None


# ── locales and zones ────────────────────────────────────────────────────

def _week_table() -> dict[str, int]:
    table: dict[str, int] = {}
    day = 1
    for code in (_WEEK_REGIONS + " " + _WEEK_LANGS).split(" "):
        if code[0] < "A":
            day, code = int(code[0]), code[1:]
        table[code] = day
    return table


_WEEK = _week_table()


_DAY3 = ("mon", "tue", "wed", "thu", "fri", "sat", "sun")
_LEAD_REGION_RE = re.compile(r"[a-z]+(-[A-Z][a-z]{3})?-([A-Z]{2}|[0-9]{3})\b",
                             re.ASCII)
_SUBDIVISION_RE = re.compile(r"([a-z]{2})\w{1,5}", re.ASCII)


def _week_start(locale: Any) -> int:
    """A locale's first ISO weekday, read in ICU's order from a canonical
    tag: ``-u-fw-`` names the day; else a region decides, ``-u-rg-``'s,
    then the region subtag, then ``-u-sd-``'s; else the language's likely
    region, through its script where that moves it (``zh-Hant`` is
    Taiwan's); else Monday. The runtime's ``D.weekStart``, line for line."""
    tag = str(locale).split("-x-")[0]
    subtags = tag.split("-")
    ext = "-" + (tag.split("-u-") + [""])[1]

    def value(key: str) -> str:
        m = re.search(rf"-{key}-(\w+)", ext, re.ASCII)
        return m.group(1) if m else ""

    def region(key: str) -> str | None:
        m = _SUBDIVISION_RE.fullmatch(value(key))
        return m.group(1) if m else None

    if value("fw") in _DAY3:
        return _DAY3.index(value("fw")) + 1
    lead = _LEAD_REGION_RE.match(tag)
    r = region("rg") or (lead and lead.group(2)) or region("sd")
    if r:
        return _WEEK.get(r.upper(), 1)
    # Lower case, so a language never reads a region's entry ("US" is not
    # the United States until it follows a language).
    lang = subtags[0].lower()
    script = f"{lang}-{subtags[1]}" if len(subtags) > 1 else ""
    return _WEEK.get(script) or _WEEK.get(lang, 1)


def _canonical_case(tag: str) -> str:
    """``tag`` in the case ``Intl.getCanonicalLocales`` writes it: the
    language in lower case, a script in title case, a region in upper case,
    and everything from the first singleton (``-u-``, ``-x-``) on in lower
    case. It is the part of canonicalising that decides a week start and
    needs no ICU: "en-gb" is en-GB, which starts on Monday, not the bare
    "en", which starts on Sunday."""
    parts = tag.split("-")
    out = [parts[0].lower()]
    for i, s in enumerate(parts[1:], 1):
        if len(s) == 1:
            return "-".join(out + [p.lower() for p in parts[i:]])
        out.append(s.title() if len(s) == 4 and s.isalpha()
                   else s.upper() if len(s) == 2 or s.isdigit()
                   else s.lower())
    return "-".join(out)


@lru_cache(maxsize=1)
def _zones() -> dict[str, str]:
    """Every zone name the tz database has, keyed by its lower case.

    The browser reads a zone name in any case ("america/new_york" is New
    York), while :class:`ZoneInfo` opens a file, which matches case only on
    a case-insensitive filesystem: on Linux the lower-case name would have
    been no zone, so Python and the page gave two answers. Built once.
    """
    return {name.lower(): name for name in available_timezones()}


def _zone(x: Any) -> str | None:
    """A zone name in the tz database's own spelling, or None for the
    system's own zone, which is also what a bad name falls back to."""
    if not (isinstance(x, str) and _ZONE_RE.fullmatch(x)):
        return None
    return _zones().get(x.lower())


def _wall(ms: int, zone: str | None) -> tuple[int, str] | None:
    """The offset (seconds) and abbreviation of a zone at an instant.

    ``datetime`` stops at years 1 and 9999 while the browser's ``Date`` does
    not, so an instant just outside them (a wall clock still inside them,
    once offset) is asked 400 years nearer the middle, where every zone's
    rule is the same one: local mean time before, the final rule after.
    """
    for shift in (0, _CYCLE_MS, -_CYCLE_MS):
        try:
            if zone is None:
                lt = time.localtime((ms + shift) // 1000)
                return lt.tm_gmtoff, lt.tm_zone
            t = (_EPOCH + timedelta(milliseconds=ms + shift)).astimezone(
                ZoneInfo(zone))
            return round(t.utcoffset().total_seconds()), t.tzname()
        except (OverflowError, ValueError, OSError):
            continue
    return None


def _offset(ms: int, zone: str | None) -> int | None:
    """The zone's offset at an instant, in ms; None where the wall clock
    would leave years 1–9999, as the runtime refuses it there."""
    s = ms - ms % 1000
    w = _wall(s, zone)
    if w is None:
        return None
    off = w[0] * 1000
    n = (s + off) // _DAY_MS
    return off if _LO <= n <= _HI else None


# ── the functions ────────────────────────────────────────────────────────

def today(zone: str | None = None, /) -> str | None:
    """Today's date in ``zone`` (an IANA name), or in the system's zone."""
    v = from_epoch(_clock(), zone)
    return v and v[:10]


def now(zone: str | None = None, seconds: bool = False, /) -> str | None:
    """Now as a datetime in ``zone``, to the minute (or to the second)."""
    v = from_epoch(_clock(), zone)
    return v and v[:19 if seconds else 16]


def is_date(s: Any, /) -> bool:
    return _p(s, "d") is not None


def is_time(s: Any, /) -> bool:
    return _p(s, "t") is not None


def is_datetime(s: Any, /) -> bool:
    return _p(s, "x") is not None


def is_month(s: Any, /) -> bool:
    return _p(s, "m") is not None


def parse(s: Any, /) -> str | None:
    """The value re-serialised, whichever kind it is: ``"2025-02-30"`` is
    None."""
    p = _parse(s)
    return _iso(p) if p else None


def make_date(y: Any, m: Any, d: Any, /) -> str | None:
    """Dart's ``DateTime(y, m, d)`` without its rollover: Feb 30 is None."""
    y, m, d = _int(y), _int(m), _int(d)
    if None in (y, m, d):
        return None
    return _chk({"k": "d", "y": y, "m": m, "d": d})


def make_time(h: Any, mi: Any, s: Any = None, /) -> str | None:
    h, mi = _int(h), _int(mi)
    sec = None if s is None else _int(s)
    if h is None or mi is None or (s is not None and sec is None):
        return None
    return _chk({"k": "t", "h": h, "mi": mi, "s": sec})


def parts(v: Any, /) -> dict | None:
    """``{year, month, day, hour, minute, second, weekday}`` with None for
    any part the value does not have, so subset code needs no ``split()``."""
    p = _parse(v)
    if not p:
        return None
    return {"year": p["y"], "month": p["m"], "day": p["d"], "hour": p["h"],
            "minute": p["mi"], "second": p["s"],
            "weekday": None if p["d"] is None else _wd(_n(p))}


def add_days(v: Any, n: Any, /) -> str | None:
    """A date or datetime moved ``n`` days; a datetime keeps its time."""
    p, n = _p(v, "dx"), _int(n)
    return _at(_n(p) + n, p) if p and n is not None else None


def add_months(v: Any, n: Any, /) -> str | None:
    """Clamped to the month's last day: Jan 31 plus a month is Feb 28.
    Accepts a date, a datetime or a month."""
    p, n = _p(v, "dmx"), _int(n)
    if not p or n is None:
        return None
    t = p["y"] * 12 + p["m"] - 1 + n
    y, m = t // 12, t % 12 + 1
    if not 0 < y < 10000:
        return None
    if p["d"] is not None:
        p["d"] = min(p["d"], _dim(y, m))
    p["y"], p["m"] = y, m
    return _iso(p)


def add_years(v: Any, n: Any, /) -> str | None:
    """Feb 29 plus a year is Feb 28."""
    n = _int(n)
    return None if n is None else add_months(v, n * 12)


def add_minutes(v: Any, n: Any, /) -> str | None:
    """A time wraps at midnight; a datetime rolls its date."""
    p, n = _p(v, "tx"), _int(n)
    if not p or n is None:
        return None
    t = p["h"] * 60 + p["mi"] + n
    carry, t = divmod(t, 1440)
    p["h"], p["mi"] = divmod(t, 60)
    return _iso(p) if p["k"] == "t" else _at(_n(p) + carry, p)


def days_between(a: Any, b: Any, /) -> int | None:
    """``b - a`` in whole days, from the date parts."""
    p, q = _p(a, "dx"), _p(b, "dx")
    return _n(q) - _n(p) if p and q else None


def month_delta(a: Any, b: Any, /) -> int | None:
    """Flutter's ``DateUtils.monthDelta``: months from ``a``'s to ``b``'s."""
    p, q = _p(a, "dmx"), _p(b, "dmx")
    return (q["y"] - p["y"]) * 12 + q["m"] - p["m"] if p and q else None


def weekday(v: Any, /) -> int | None:
    """1 (Monday) to 7 (Sunday), Dart's ``DateTime.weekday``."""
    p = _p(v, "dx")
    return _wd(_n(p)) if p else None


def days_in_month(y: Any, m: Any, /) -> int | None:
    y, m = _int(y), _int(m)
    if y is None or m is None or not (0 < y < 10000 and 0 < m < 13):
        return None
    return _dim(y, m)


def is_leap_year(y: Any, /) -> bool:
    y = _int(y)
    return y is not None and 0 < y < 10000 and _leap(y)


def _week_bound(v: Any, first: Any, plus: int) -> str | None:
    p = _p(v, "dx")
    # None is the locale's first day; the twin's locale is en-US, Sunday.
    first = _week_start("en-US") if first is None else _int(first)
    if not p or first is None or not 0 < first < 8:
        return None
    n = _n(p)
    return _at(n - (_wd(n) - first + 7) % 7 + plus, p, "d")


def start_of_week(v: Any, first: Any = None, /) -> str | None:
    """The first day of ``v``'s week, which starts on ISO weekday
    ``first`` (None: Sunday here, the locale's day in a page)."""
    return _week_bound(v, first, 0)


def end_of_week(v: Any, first: Any = None, /) -> str | None:
    return _week_bound(v, first, 6)


def week_start(locale: Any = None, /) -> int:
    """The ISO weekday a week starts on in ``locale``, 1 (Monday) to 7
    (Sunday): the day a calendar given that ``locale`` starts its rows on,
    so code beside it can start a week on the same day.

    None, or anything that is no BCP 47 tag, is the page's language in a
    page and en-US (Sunday) here, as ``start_of_week``'s None is. A tag is
    read in its canonical case; an alias the browser maps to another
    language ("iw" for Hebrew) is the browser's alone, so where the two must
    agree, give the language's own tag."""
    ok = (isinstance(locale, str) and len(locale) <= 64
          and _LOCALE_RE.fullmatch(locale))
    return _week_start(_canonical_case(locale) if ok else "en-US")


def start_of_month(v: Any, /) -> str | None:
    p = _p(v, "dmx")
    return _iso({"y": p["y"], "m": p["m"], "d": 1}, "d") if p else None


def end_of_month(v: Any, /) -> str | None:
    p = _p(v, "dmx")
    if not p:
        return None
    return _iso({"y": p["y"], "m": p["m"], "d": _dim(p["y"], p["m"])}, "d")


def month_of(v: Any, /) -> str | None:
    """``"2025-12"`` for any date, datetime or month in December 2025."""
    p = _p(v, "dmx")
    return _iso(p, "m") if p else None


def next_weekday(v: Any, wd: Any, inclusive: Any = False, /) -> str | None:
    """The first ISO weekday ``wd`` after ``v``, or on or after it when
    ``inclusive``."""
    p, wd = _p(v, "dx"), _int(wd)
    if not p or wd is None or not 0 < wd < 8:
        return None
    n = _n(p)
    return _at(n + ((wd - _wd(n) + 7) % 7 or (0 if inclusive else 7)), p, "d")


def is_same_day(a: Any, b: Any, /) -> bool:
    p, q = _p(a, "dx"), _p(b, "dx")
    return bool(p and q and _n(p) == _n(q))


def is_same_month(a: Any, b: Any, /) -> bool:
    p, q = _p(a, "dmx"), _p(b, "dmx")
    return bool(p and q and p["y"] == q["y"] and p["m"] == q["m"])


def combine(d: Any, t: Any, /) -> str | None:
    """A datetime from a date (or a datetime's date) and a time (or a
    datetime's time)."""
    p, q = _p(d, "dx"), _p(t, "tx")
    if not (p and q):
        return None
    return _iso({"y": p["y"], "m": p["m"], "d": p["d"], "h": q["h"],
                 "mi": q["mi"], "s": q["s"]}, "x")


def date_of(v: Any, /) -> str | None:
    p = _p(v, "dx")
    return _iso(p, "d") if p else None


def time_of(v: Any, /) -> str | None:
    p = _p(v, "tx")
    return _iso(p, "t") if p else None


def clamp(v: Any, first: Any, last: Any, /) -> str | None:
    """``v`` held inside ``[first, last]``. A bound left as None is open; a
    bound that is not a date, or a pair in the wrong order, is None rather
    than a guess."""
    p = _p(v, "d")
    a = _LO if first is None else _p(first, "d")
    b = _HI if last is None else _p(last, "d")
    if isinstance(a, dict):
        a = _n(a)
    if isinstance(b, dict):
        b = _n(b)
    if not p or a is None or b is None or a > b:
        return None
    return _at(min(max(_n(p), a), b), p)


# ── formatting (en-US) ───────────────────────────────────────────────────

_MONTHS = ("January", "February", "March", "April", "May", "June", "July",
           "August", "September", "October", "November", "December")
_DAYS = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday",
         "Saturday", "Sunday")
STYLES = ("full", "long", "medium", "short", "month_year", "month_day",
          "weekday", "weekday_short", "day", "time", "time_seconds",
          "datetime")
RANGE_STYLES = ("full", "long", "medium", "short", "month_year",
                "month_day")
# ICU's own abbreviation separates a range's two ends with thin spaces.
_DASH = " – "


def _kinds(style: str) -> str:
    """Which kinds a style can show: the date styles need a date (or a
    datetime's), month_year also takes a month, the two time styles a time
    (or a datetime's), and datetime a datetime."""
    if style == "datetime":
        return "x"
    if style.startswith("time"):
        return "tx"
    return "dmx" if style == "month_year" else "dx"


def _pick(style: Any, allowed: tuple) -> str:
    return style if isinstance(style, str) and style in allowed else "medium"


def _en(p: dict, style: str) -> str:
    y, m, d = p["y"], p["m"], p["d"]
    if style.startswith("time") or style == "datetime":
        h, mi = p["h"], p["mi"]
        clock = f"{h % 12 or 12}:{mi:02d}"
        if style == "time_seconds":
            clock += f":{p['s'] or 0:02d}"
        clock += " AM" if h < 12 else " PM"
        if style != "datetime":
            return clock
        return f"{_en(p, 'medium')}, {clock}"
    if style == "month_year":
        return f"{_MONTHS[m - 1]} {y}"
    if style in ("weekday", "weekday_short"):
        name = _DAYS[_wd(_n(p)) - 1]
        return name if style == "weekday" else name[:3]
    if style == "day":
        return str(d)
    if style == "month_day":
        return f"{_MONTHS[m - 1][:3]} {d}"
    if style == "short":
        return f"{m}/{d}/{y % 100:02d}"
    month = _MONTHS[m - 1][:3] if style == "medium" else _MONTHS[m - 1]
    text = f"{month} {d}, {y}"
    return f"{_DAYS[_wd(_n(p)) - 1]}, {text}" if style == "full" else text


def format(v: Any, style: Any = "medium", locale: Any = None,  # noqa: A001
           zone: Any = None, /) -> str | None:
    """Display text for a value, in one of :data:`STYLES`.

    An instant (epoch milliseconds) is first read as wall-clock time in
    ``zone``. A style the value cannot show (``"time"`` for a date) is
    None. Here the text is always en-US; ``locale`` matters in a page.
    """
    if _int(v) is not None and not isinstance(v, str):
        v = from_epoch(v, zone)
    style = _pick(style, STYLES)
    p = _p(v, _kinds(style))
    return _en(p, style) if p else None


def format_range(a: Any, b: Any, style: Any = "medium",
                 locale: Any = None, /) -> str | None:
    """Two dates as one range, as ICU's ``formatRange`` writes it in en-US:
    ``"Dec 16 – 24, 2025"``. ``style`` is one of :data:`RANGE_STYLES`."""
    p, q = _p(a, "dx"), _p(b, "dx")
    if not (p and q):
        return None
    style = _pick(style, RANGE_STYLES)
    start, end = _en(p, style), _en(q, style)
    same_y = p["y"] == q["y"]
    same_m = same_y and p["m"] == q["m"]
    if same_m and (style == "month_year" or p["d"] == q["d"]):
        return start
    if style == "short" or not same_y:
        if style == "month_day":
            return _en(p, "medium") + _DASH + _en(q, "medium")
        return start + _DASH + end
    year = p["y"]
    if style == "month_year":
        return f"{_MONTHS[p['m'] - 1]}{_DASH}{_MONTHS[q['m'] - 1]} {year}"
    if style == "full":
        return f"{start.rsplit(',', 1)[0]}{_DASH}{end}"
    names = [n[:3] if style in ("medium", "month_day") else n
             for n in (_MONTHS[p["m"] - 1], _MONTHS[q["m"] - 1])]
    tail = "" if style == "month_day" else f", {year}"
    if same_m:
        return f"{names[0]} {p['d']}{_DASH}{q['d']}{tail}"
    return f"{names[0]} {p['d']}{_DASH}{names[1]} {q['d']}{tail}"


# ── instants and zones ───────────────────────────────────────────────────

def to_epoch(v: Any, zone: Any = None, /) -> int | None:
    """The instant (epoch ms) of a wall-clock date or datetime in ``zone``.

    Read the way Temporal's ``"compatible"`` does: a time in a
    spring-forward gap moves forward by the gap (New York's
    ``2025-03-09T02:30`` is 07:30Z), and one in a fall-back overlap takes
    the earlier instant (``2025-11-02T01:30`` is 05:30Z). The offsets a day
    either side are the candidates, each kept only if the zone agrees with
    it there.
    """
    p = _p(v, "dx")
    if not p:
        return None
    zone = _zone(zone)
    w = (_n(p) * _DAY_MS + (p["h"] or 0) * 3_600_000
         + (p["mi"] or 0) * 60_000 + (p["s"] or 0) * 1000)
    a, b = _offset(w - _DAY_MS, zone), _offset(w + _DAY_MS, zone)
    if a is None or b is None:
        return None
    if _offset(w - b, zone) == b and not (_offset(w - a, zone) == a and a > b):
        return w - b
    return w - a


def from_epoch(ms: Any, zone: Any = None, /) -> str | None:
    """The wall-clock datetime, to the second, of an instant in ``zone``."""
    ms = _int(ms)
    if ms is None:
        return None
    off = _offset(ms, _zone(zone))
    if off is None:
        return None
    n, r = divmod(ms + off, _DAY_MS)
    return _at(n, {"h": r // 3_600_000, "mi": r // 60_000 % 60,
                   "s": r // 1000 % 60}, "x")


# ICU's en-US short names. Any other zone is written as its offset.
_US_NAMES = {"EST": -5, "EDT": -4, "CST": -6, "CDT": -5, "MST": -7,
             "MDT": -6, "PST": -8, "PDT": -7, "AKST": -9, "AKDT": -8,
             "HST": -10, "AST": -4, "ADT": -3, "UTC": 0}


def zone_name(v: Any = None, zone: Any = None, /) -> str | None:
    """The zone's short name on ``v``'s date (EST in December, EDT in
    July), or now when ``v`` is None. A date is read at noon, clear of any
    change. As ICU writes it in en-US: a US zone by its letters, any other
    by its offset (``GMT+1``, ``GMT+5:45``)."""
    if v is None:
        ms = _clock()
    else:
        ms = to_epoch(v + "T12:00" if is_date(v) else v, zone)
    w = None if ms is None else _wall(ms, _zone(zone))
    if w is None:
        return None
    off, abbr = w
    if abbr in _US_NAMES and _US_NAMES[abbr] * 3600 == off:
        return abbr
    if off == 0:
        return "GMT"
    h, rest = divmod(abs(off), 3600)
    mi, s = divmod(rest, 60)
    text = f"GMT{'+' if off > 0 else '-'}{h}"
    if mi or s:
        text += f":{mi:02d}"
    if s:
        text += f":{s:02d}"
    return text
